import{_ as a,o as s,c as t,a4 as i}from"./chunks/framework.DA9C4Pbl.js";const k=JSON.parse('{"title":"arcsecond allsky","description":"","frontmatter":{"title":"arcsecond allsky","visibility":"public","audience":"operator","tier":"reference","source":"generated","cli":"4.2.1"},"headers":[],"relativePath":"reference/commands/allsky.md","filePath":"reference/commands/allsky.md"}'),l={name:"reference/commands/allsky.md"};function o(r,e,n,d,c,h){return s(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="arcsecond-allsky" tabindex="-1"><code>arcsecond allsky</code> <a class="header-anchor" href="#arcsecond-allsky" aria-label="Permalink to “arcsecond allsky”">​</a></h1><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>arcsecond allsky [OPTIONS] [COMMAND] [ARGS]...</span></span></code></pre></div><p>List your all-sky cameras.</p><p>With no sub-command, prints what is registered and probes nothing. Use <code>detect</code> to look at well-known locations, <code>add</code> to register a camera and <code>forget</code> to drop one.</p><p><strong>Subcommands</strong></p><ul><li><a href="#arcsecond-allsky-add"><code>arcsecond allsky add</code></a> — Register an all-sky camera, so that the proxy serves it.</li><li><a href="#arcsecond-allsky-detect"><code>arcsecond allsky detect</code></a> — Look for all-sky cameras at well-known paths (Thomas Jacquin&#39;s allsky, indi-allsky) and report how they line up with...</li><li><a href="#arcsecond-allsky-forget"><code>arcsecond allsky forget</code></a> — Stop remembering an all-sky camera.</li></ul><h2 id="arcsecond-allsky-add" tabindex="-1"><code>arcsecond allsky add</code> <a class="header-anchor" href="#arcsecond-allsky-add" aria-label="Permalink to “arcsecond allsky add”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>arcsecond allsky add [OPTIONS] TARGET</span></span></code></pre></div><p>Register an all-sky camera, so that the proxy serves it.</p><p>TARGET is the JPEG your all-sky software keeps up to date. Give a path when that software runs on this machine — a fixed file, a symlink, or a glob, in which case the newest matching file wins — or an <code>http://...</code> address when it runs on another machine and publishes the image. Write a password as ${VARIABLE} to keep it out of your shell history: only the variable name is written to disk.</p><p>Prints the camera&#39;s id. That id is the only handle you need afterwards, and it does not change.</p><p><strong>Arguments</strong></p><ul><li><code>TARGET</code> — required</li></ul><p><strong>Options</strong></p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>--label TEXT</code></td><td>A name for yourself, e.g. &#39;Roof&#39;.</td></tr></tbody></table><h2 id="arcsecond-allsky-detect" tabindex="-1"><code>arcsecond allsky detect</code> <a class="header-anchor" href="#arcsecond-allsky-detect" aria-label="Permalink to “arcsecond allsky detect”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>arcsecond allsky detect [OPTIONS]</span></span></code></pre></div><p>Look for all-sky cameras at well-known paths (Thomas Jacquin&#39;s allsky, indi-allsky) and report how they line up with what is registered.</p><p>Registers nothing. A registered camera writing somewhere else is confirmed by looking at its own path, so it is not reported missing merely for being somewhere unusual.</p><h2 id="arcsecond-allsky-forget" tabindex="-1"><code>arcsecond allsky forget</code> <a class="header-anchor" href="#arcsecond-allsky-forget" aria-label="Permalink to “arcsecond allsky forget”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>arcsecond allsky forget [OPTIONS] CAMERA_ID</span></span></code></pre></div><p>Stop remembering an all-sky camera. Give the id printed by <code>arcsecond allsky</code>, e.g. <code>r4t</code>.</p><p>If the proxy is running, it stops serving the camera straight away.</p><p><strong>Arguments</strong></p><ul><li><code>CAMERA_ID</code> — required</li></ul>',25)])])}const g=a(l,[["render",o]]);export{k as __pageData,g as default};
